<script setup lang="ts">import {onMounted,onUnmounted,ref,watch} from 'vue';const props=withDefaults(defineProps<{value:number;duration?:number;locale?:string;maximumFractionDigits?:number}>(),{duration:450,locale:'en-GB',maximumFractionDigits:0});const shown=ref(props.value);let raf=0;function animate(target:number){cancelAnimationFrame(raf);if(typeof window==='undefined'||window.matchMedia('(prefers-reduced-motion: reduce)').matches){shown.value=target;return}const from=shown.value,start=performance.now();function frame(t:number){const p=Math.min(1,(t-start)/Math.max(1,props.duration));shown.value=from+(target-from)*(1-Math.pow(1-p,3));if(p<1)raf=requestAnimationFrame(frame)}raf=requestAnimationFrame(frame)}watch(()=>props.value,animate);onMounted(()=>animate(props.value));onUnmounted(()=>cancelAnimationFrame(raf));</script><template><span>{{new Intl.NumberFormat(locale,{maximumFractionDigits}).format(shown)}}</span></template>